head.script:
scwin.onpageload = function () {
	imports("uiplugin.popup");
};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
	var options = {
		id: "popWframe",
		title: "popupTest",
		type: "wframePopup",
		width: "700px",
		height: "500px",
        frameModal: true,
		popupName: "wframePopup"
	};

    if (WebSquare.strictModeFrame) {
	   $p.openPopup("wframePopup_frameModal_WESD-1207_(WSQ-5165)_sub.xml", options);
    } else {
        WebSquare.util.openPopup("wframePopup_frameModal_WESD-1207_(WSQ-5165)_sub.xml", options);
    }
};

	scwin.checkVal = function() {
		var temp = WebSquare.logger.getErrorLog();
		return temp == '';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");			

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
